contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }
    function testFuzz_property(address from, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        AmountRecorder recorder = new AmountRecorder();
        vm.assume(from != address(0));
        vm.prank(from);
        c.transfer(from, address(recorder), _tos, v);
        assertTrue(recorder.lastAmount() == v);
    }
}

contract AmountRecorder {
    uint256 public lastAmount;
    function transferFrom(address, address, uint256 amount) external returns (bool) {
        lastAmount = amount;
        return true;
    }
}
